// ===================== CONFIGURAÇÃO (preencha uma vez) =====================
// Token que a Lastlink mostra na tela do webhook (o mesmo que chega no cabeçalho x-lastlink-token)
const TOKEN_LASTLINK = 'COLE_AQUI_O_TOKEN_DA_LASTLINK';
// Endereço do app das alunas, sem barra no fim. Ex.: https://app.lnobrega.com
const APP_URL = 'https://metodo.lnobrega.com';
// Parte do nome do produto na Lastlink. Deixe '' pra aceitar tudo o que chegar neste webhook.
const PRODUTO_CONTEM = '';
// ===========================================================================
const SUPABASE_URL = 'https://ivfgpircfwwgpumrrcwp.supabase.co';
if (TOKEN_LASTLINK.includes('COLE_AQUI')) {
  throw new Error('Preencha o TOKEN_LASTLINK no topo do nó "Conferir e preparar".');
}

const req = $input.first().json;
const token = (req.headers && req.headers['x-lastlink-token']) || '';
if (token !== TOKEN_LASTLINK) throw new Error('Token da Lastlink não confere. Pedido ignorado por segurança.');

const body = req.body || {};
const data = body.Data || {};
const buyer = data.Buyer || {};
const purchase = data.Purchase || {};
const evento = body.Event || '';
const email = String(buyer.Email || '').toLowerCase().trim();
if (!email) throw new Error('A Lastlink mandou um evento sem e-mail.');

const produtos = (data.Products || []).map((p) => p.Name).filter(Boolean).join(', ');
const LIBERAR = ['Purchase_Order_Confirmed', 'Recurrent_Payment'];
const BLOQUEAR = { Payment_Refund: 'reembolsada', Payment_Chargeback: 'cancelada' };

let acao = 'ignorar';
if (LIBERAR.includes(evento)) acao = 'liberar';
else if (BLOQUEAR[evento]) acao = 'bloquear';
if (PRODUTO_CONTEM && !produtos.toLowerCase().includes(PRODUTO_CONTEM.toLowerCase())) acao = 'ignorar';

// A Lastlink manda a data sem fuso: é horário de Brasília
const pd = purchase.PaymentDate;
const dataCompra = pd ? (/(z|[+-]\d\d:?\d\d)$/i.test(pd) ? pd : pd + '-03:00') : new Date().toISOString();

return [{
  json: {
    acao,
    evento,
    status_bloqueio: BLOQUEAR[evento] || null,
    email,
    nome: String(buyer.Name || '').trim(),
    telefone: String(buyer.PhoneNumber || '').trim(),
    pedido: purchase.PaymentId || '',
    data_compra: dataCompra,
    oferta: (data.Offer && data.Offer.Name) || '',
    produtos,
    valor: purchase.Price && purchase.Price.Value != null ? purchase.Price.Value : '',
    teste: body.IsTest ? 'Sim' : 'Não',
    app_url: APP_URL.replace(/\/$/, ''),
    supabase_url: SUPABASE_URL,
  },
}];

const d = $('Conferir e preparar').first().json;
const r = $input.first().json || {};
const resultado = r.resultado || 'ignorado';
const TEXTOS = {
  nova: 'Acesso liberado (aluna nova)',
  renovada: 'Acesso renovado por 1 ano',
  sem_login: 'ERRO: o login não foi criado. Confira o SMTP do Supabase e rode de novo',
  bloqueada: 'Acesso bloqueado (' + (d.status_bloqueio || '') + ')',
  nao_encontrada: 'Reembolso de alguém que não está no app',
  ignorado: 'Evento ignorado',
};

let convite = '';
if (d.acao === 'liberar') {
  try {
    const c = $('Enviar convite').first().json;
    if (c.error) {
      const txt = JSON.stringify(c.error);
      convite = /already|registered|email_exists/i.test(txt) ? 'Já tinha login' : 'Não enviado: ' + txt.slice(0, 120);
    } else {
      convite = 'Enviado';
    }
  } catch (e) {
    convite = '';
  }
}

return [{
  json: {
    'Data': new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    'Evento': d.evento,
    'Nome': d.nome,
    'E-mail': d.email,
    'WhatsApp': d.telefone,
    'Produto': d.produtos,
    'Oferta': d.oferta,
    'Valor': d.valor,
    'Pedido': d.pedido,
    'Resultado': TEXTOS[resultado] || resultado,
    'E-mail de acesso': convite,
    'Teste': d.teste,
  },
}];

// Se algo deu errado, a execução fica vermelha no n8n pra você ver.
const r = $('Montar linha da planilha').first().json;
if (String(r['Resultado']).startsWith('ERRO')) throw new Error(r['Resultado'] + ' (' + r['E-mail'] + ')');
return $input.all();
